mapper.select:
SELECT la.logistics_platform, lc.id AS channelId, la.id AS authId FROM logistics_auth la INNER JOIN logistics_supplier ls ON ls.id=la.main_id AND ls.is_deleted=false INNER JOIN logistics_channel lc ON lc.main_id=ls.id AND lc.is_deleted=false WHERE la.is_deleted=false
and lc.id in
#{item}

SELECT lc.id as channelId, lc.code as channelCode, ls.supplier_id as logisticsSupplierId, ls.supplier_name as logisticsSupplierName from logistics_channel lc inner join logistics_supplier ls on lc.main_id = ls.id where lc.is_deleted = false and ls.is_deleted = false and ls.disabled = false and auth_status = 'already' and lc.disabled = false
and lc.code in
#{item}
and ls.supplier_name in
#{item}

select
from logistics_channel lc where lc.is_deleted = false
and ${params.sqlMap.detail}
and lc.main_id in
#{item}
order by lc.disabled asc,lc.create_time desc

select id,name as value,code,disabled,logisticsSupplierId,logisticsSupplierName from ( select lc.id, lc.name, lc.code, lc.disabled, ls.id as logisticsSupplierId, ls.short_name as logisticsSupplierName from logistics_channel lc left join logistics_supplier ls on ls.id = lc.main_id and ls.is_deleted = false left join logistics_auth la on ls.id = la.main_id and la.is_deleted = false where lc.is_deleted = false and ls.id is not null
and ((lc.code = #{params.searchKeyword}) or (lc.id = #{params.searchKeyword}) or lc.name ilike concat('%', #{params.searchKeyword}::text ,'%'))
and ls.id = #{params.supplierId}
and lc.disabled=#{params.disabled}
and la.logistics_platform = #{params.logisticsPlatform}
order by lc.disabled asc,
case when lc.name ILIKE concat(#{params.searchKeyword}::text,'%') THEN 1 when lc.name ILIKE concat('%',#{params.searchKeyword}::text) THEN 2 when lc.name ILIKE concat('%',#{params.searchKeyword}::text,'%') THEN 3 end , lc.name,
code asc ) wls

select lc.name as channelName, count(lbd.id) as total from logistics_bill_detail lbd inner join logistics_bill lb on lbd.main_id = lb.id and lb.is_deleted = false LEFT JOIN logistics_channel lc on lb.channel_id = lc.id and lc.is_deleted = false where lbd.track_status not in('sign','manualComplete','systemComplete','deliveryFail') and (lbd.track_no != '' or lb.transport_no != '') and lbd.is_deleted = false AND lc.name != ''
and lbd.update_time < #{query.updateTime}
and lbd.track_time > #{query.trackTime}
and lb.order_type in ('B2B','B2C','AfterSale')
and lb.order_type = 'firstMile'
and (lc.track_query_mode = #{query.trackQueryMode} or lc.track_query_mode is NULL)
and lbd.register_status = #{query.registerStatus}
and lbd.track_enable = #{query.trackEnable}
and lbd.track_no in
#{item}
and lb.transport_no in
#{item}
GROUP BY channelName ORDER BY total desc

select lc.id as channelId, lc.code as channelCode, lc.name as channelName, lc.effective_time, lc.effective_time_unit, lc.shipment_over_limit_rate as shipmentOverLimitRate, ls.supplier_id, ls.supplier_name, lcw."type", lcw.warehouse_id from logistics_channel lc LEFT JOIN logistics_supplier ls on ls.id = lc.main_id and ls.is_deleted = FALSE LEFT JOIN logistics_auth la on la.main_id = lc.main_id and la.is_deleted = FALSE LEFT JOIN logistics_channel_warehouse lcw on lc.id = lcw.logistics_channel_id and lcw.is_deleted = FALSE where lc.is_deleted = FALSE
and la.logistics_platform = #{platform}
and ls.auth_status = #{authStatus}
and ls."type" = #{warehousePlatformType}
and lc.disabled = #{disabled}

select  lc.code,lc.cn_name as name,true as status from logistics_sale_channel lc
where lc.is_deleted = false and lc.overseas_warehouse_id = #{dto.platformWarehouseId}

    and lc.channel_type = #{dto.channelType}
